import{_ as t,c as e,o as r,ak as i}from"./chunks/framework.gmyagHYt.js";const m=JSON.parse('{"title":"主界面介绍","description":"对主界面中各部分内容进行介绍","frontmatter":{"title":"主界面介绍","description":"对主界面中各部分内容进行介绍","layout":"doc"},"headers":[],"relativePath":"version/v3/docs/base/ui-Introduction/main-Interface.md","filePath":"version/v3/docs/base/ui-Introduction/main-Interface.md","contributors":[{"name":"晚安","username":"nulijiazaizhong","avatar":"https://github.com/nulijiazaizhong.png?size=64","commits":1,"profileUrl":"https://github.com/nulijiazaizhong"}]}'),s={name:"version/v3/docs/base/ui-Introduction/main-Interface.md"};function n(l,a,c,o,h,p){return r(),e("div",null,[...a[0]||(a[0]=[i('<p><img src="https://tc.ets2la.cn/csharp/20260927091438793.png" alt="" loading="lazy"> 从上面的图片中可以看到主界面ui分为了两个部分——侧边栏和功能区；侧边栏中有很多的模块，接下来以此介绍各个模块的作用是什么。</p><h2 id="仪表盘" tabindex="-1">仪表盘 <a class="header-anchor" href="#仪表盘" aria-label="Permalink to “仪表盘”">​</a></h2><p>仪表盘目前显示的是项目在GitHub上的赞助信息，包含了赞助链接和赞助用户名单的公示</p><h2 id="可视化" tabindex="-1">可视化 <a class="header-anchor" href="#可视化" aria-label="Permalink to “可视化”">​</a></h2><p>顾名思义就是用于显示插件/软件运行状态的显示，在未启用 <code>Visuakization Sockets</code> 插件的情况下显示的图一所示， <img src="https://tc.ets2la.cn/csharp/20260927091835592.png" alt="图一" loading="lazy"> 在启用了插件的情况下如图二所示 <img src="https://tc.ets2la.cn/csharp/20260927092125912.png" alt="图二" loading="lazy"></p><h2 id="插件管理" tabindex="-1">插件管理 <a class="header-anchor" href="#插件管理" aria-label="Permalink to “插件管理”">​</a></h2><p>插件管理页面中会显示所有<strong>已安装</strong>的插件，可以单独启用，也可以使用一键命令全部启用<br> 点击红色方框会在资源管理器中打开插件文件夹，点击黄色方框会重新刷新所有已安装的插件 <img src="https://tc.ets2la.cn/csharp/20260927092433323.png" alt="" loading="lazy"></p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>软件更新会删除本地插件文件夹中的所有文件，需要在插件库中重新安装</p></div><h2 id="插件库" tabindex="-1">插件库 <a class="header-anchor" href="#插件库" aria-label="Permalink to “插件库”">​</a></h2><p>插件库是安装插件的地方，你可以在这里看见很多插件，这里有ETS2LA开发组编写的插件，也有许多第三方开发者编写的插件，请注意区分；找到对应的插件点击安装即可，插件安装完成之后会要求重启软件，按照要求重启即可。 <img src="https://tc.ets2la.cn/csharp/20260927092742275.png" alt="" loading="lazy"></p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果你的插件库是空的，请确保你是从官方地址下载的软件安装包，因为这关系到软件在后端使用什么插件源；<br> 安装包与插件源对应关系：<br> GitHub/sourceforge ——&gt; 官方地址（使用 cloudflare 进行分发）<br> CNB/国内镜像站 ——&gt; 国内镜像地址（使用华为云CDN进行分发）</p></div><h2 id="维基-常见问题" tabindex="-1">维基/常见问题 <a class="header-anchor" href="#维基-常见问题" aria-label="Permalink to “维基/常见问题”">​</a></h2><p>该页面显示的是 <a href="https://ets2la.com/help/faq/" target="_blank" rel="noreferrer">https://ets2la.com/help/faq/</a> 该网页链接的内容</p><h2 id="联系我们" tabindex="-1">联系我们 <a class="header-anchor" href="#联系我们" aria-label="Permalink to “联系我们”">​</a></h2><p>如果软件在使用过程中遇到恶行bug，可通过该页面中的地址联系开发者 <img src="https://tc.ets2la.cn/csharp/20260927094729873.png" alt="" loading="lazy"></p><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to “设置”">​</a></h2><p>软件的设置都在该页面中，包括但不限于数据精度的选择；该页面中的修改项大部分都有对应的描述，所以这里不多讲。 <img src="https://tc.ets2la.cn/csharp/20260927094842516.png" alt="" loading="lazy"></p><h2 id="匿名" tabindex="-1">匿名 <a class="header-anchor" href="#匿名" aria-label="Permalink to “匿名”">​</a></h2><p>这是用户系统的快捷入口，由于用户系统暂未完成开发，所以你看到的界面应该是这样的 <img src="https://tc.ets2la.cn/csharp/20260927095049793.png" alt="" loading="lazy"></p>',19)])])}const g=t(s,[["render",n]]);export{m as __pageData,g as default};
